# -----------------------------------------------------------------------------
# Embedded Vej/QGIS template data (metres, normalized to straight-path axes)
# -----------------------------------------------------------------------------
_TEMPLATE_B64 = """"""
_TEMPLATE_CACHE = None


def templates():
    global _TEMPLATE_CACHE
    if _TEMPLATE_CACHE is None:
        raw = zlib.decompress(base64.b64decode(_TEMPLATE_B64.encode("ascii")))
        _TEMPLATE_CACHE = json.loads(raw.decode("utf-8"))
    return _TEMPLATE_CACHE


# QGIS typeid mapping from the uploaded Korekurver v1.2 plugin.
