    {"key":"REN", "label":"REN - Renovationskøretøj", "modes":{"A":2, "B":102}},
    {"key":"LV", "label":"LV - Lastvogn", "modes":{"A":3, "B":103}},
    {"key":"PV", "label":"PV - Person- og varevogn", "modes":{"A":1, "B":101}},
    {"key":"BUS12", "label":"BUS 12 - 12 m bus", "modes":{"A":4, "B":104}},
    {"key":"BUS13", "label":"BUS 13.7 - 13.7 m bus", "modes":{"A":5, "B":105}},
    {"key":"BUS15", "label":"BUS 15 - 15 m bus", "modes":{"A":6, "B":106}},
    {"key":"BUS25", "label":"BUS 25 - 25 m articulated bus", "modes":{"A":7, "B":107}},
