MODE_LABELS = ["A - normal/free movement", "B - constrained / low speed"]
ROAD_LAYOUT_LABELS = ["Single-lane / shared road", "Two-way road - right-hand traffic"]
STICKY_PREFIX = "VehicleTurnVD12."


# -----------------------------------------------------------------------------
# Basic helpers / units
# -----------------------------------------------------------------------------
def clamp(x, a, b):
    return max(a, min(b, x))


def cross2(a, b):
    return a[0]*b[1] - a[1]*b[0]


def dot2(a, b):
    return a[0]*b[0] + a[1]*b[1]


def unit2(x, y):
    L = math.hypot(x, y)
    if L <= 1e-12:
        return None
    return (x/L, y/L)


def left2(d):
    return (-d[1], d[0])


def right2(d):
    return (d[1], -d[0])


def add2(p, d, s=1.0):
    return (p[0] + d[0]*s, p[1] + d[1]*s)


def sub2(a,b):
    return (a[0]-b[0], a[1]-b[1])


_UNIT_SYSTEM = None
_M_TO_MODEL = 1.0
_MODEL_TO_M = 1.0


def refresh_units():
    global _UNIT_SYSTEM, _M_TO_MODEL, _MODEL_TO_M
    us = sc.doc.ModelUnitSystem
    if us != _UNIT_SYSTEM:
        _UNIT_SYSTEM = us
        _M_TO_MODEL = Rhino.RhinoMath.UnitScale(Rhino.UnitSystem.Meters, us)
        _MODEL_TO_M = Rhino.RhinoMath.UnitScale(us, Rhino.UnitSystem.Meters)


def m2model(v):
    refresh_units()
    return float(v) * _M_TO_MODEL


def model2m(v):
    refresh_units()
    return float(v) * _MODEL_TO_M


def sticky_get(key, default):
    k = STICKY_PREFIX + key
    return sc.sticky[k] if k in sc.sticky else default


def sticky_int(key, default, lo, hi):
    try: v = int(sticky_get(key, default))
    except Exception: v = int(default)
    return int(clamp(v, lo, hi))


def sticky_float(key, default, lo, hi):
    try:
        v = float(sticky_get(key, default))
        if not math.isfinite(v): raise ValueError()
    except Exception:
        v = float(default)
    return clamp(v, lo, hi)


def sticky_bool(key, default):
    v = sticky_get(key, default)
    if isinstance(v, bool): return v
    if isinstance(v, (int,float)): return bool(v)
    if isinstance(v, str): return v.strip().lower() in ("1","true","yes","on")
    return bool(default)


# -----------------------------------------------------------------------------
# Rhino / Eto helpers
# -----------------------------------------------------------------------------
def make_label(text, width=None):
    lbl = ef.Label()
    lbl.Text = str(text)
    if width is not None:
        lbl.Width = width
    lbl.VerticalAlignment = ef.VerticalAlignment.Center
    return lbl


def make_stepper(value, lo, hi, step, decimals):
    s = ef.NumericStepper()
    s.MinValue = lo
    s.MaxValue = hi
    s.Increment = step
    s.DecimalPlaces = decimals
    s.Value = value
    return s


def get_linear_curve(prompt):
    go = ric.GetObject()
    go.SetCommandPrompt(prompt)
    go.GeometryFilter = rd.ObjectType.Curve
    go.SubObjectSelect = False
    try:
        go.EnablePreSelect(False, True)
    except Exception:
        pass
    go.Get()
    if go.CommandResult() != Rhino.Commands.Result.Success:
        return None, None, None
    ref = go.Object(0)
    crv = ref.Curve()
    tol = sc.doc.ModelAbsoluteTolerance
    if crv is None or crv.IsClosed or not crv.IsLinear(tol):
        rui.Dialogs.ShowMessage("Select an OPEN straight line / linear curve.", "Vehicle Turn")
        try: sc.doc.Objects.UnselectAll()
        except Exception: pass
        return None, None, None
    line = rg.Line(crv.PointAtStart, crv.PointAtEnd)
    pick = ref.SelectionPoint()
    if not pick.IsValid:
        pick = crv.PointAt(crv.Domain.Mid)
    try:
        sc.doc.Objects.UnselectAll()
        sc.doc.Views.Redraw()
    except Exception:
        pass
    return ref, line, pick


def infinite_line_intersection(p, u, q, v):
    den = cross2(u, v)
    if abs(den) <= 1e-12:
        return None
    qp = (q[0]-p[0], q[1]-p[1])
    t = cross2(qp, v) / den
    return (p[0]+u[0]*t, p[1]+u[1]*t)


def line_xy(line):
    p=(line.From.X,line.From.Y)
    d=unit2(line.To.X-line.From.X, line.To.Y-line.From.Y)
    return p,d


def infinite_plan_intersection(line_a, line_b):
    p,u=line_xy(line_a); q,v=line_xy(line_b)
    if u is None or v is None: return None
    return infinite_line_intersection(p,u,q,v)


def line_z_at_xy(line, xy):
    rx=line.To.X-line.From.X; ry=line.To.Y-line.From.Y
    rr=rx*rx+ry*ry
    if rr<=1e-20: return line.From.Z
    t=((xy[0]-line.From.X)*rx+(xy[1]-line.From.Y)*ry)/rr
    return line.From.Z+t*(line.To.Z-line.From.Z)


def line_grade(line, travel_dir):
    dx=line.To.X-line.From.X; dy=line.To.Y-line.From.Y
    h=math.hypot(dx,dy)
    if h<=1e-12: return 0.0
    raw=(dx/h,dy/h)
    g=(line.To.Z-line.From.Z)/h
    return g if dot2(raw,travel_dir)>=0 else -g


def distance_to_infinite_line(xy, line):
    p,d=line_xy(line)
    if d is None: return 0.0
    return abs(cross2(sub2(xy,p), d))


def blended_z(xy, line_in, line_out):
    zi=line_z_at_xy(line_in,xy)
    zo=line_z_at_xy(line_out,xy)
    di=distance_to_infinite_line(xy,line_in)
    do=distance_to_infinite_line(xy,line_out)
    s=di+do
    if s<=sc.doc.ModelAbsoluteTolerance:
        return 0.5*(zi+zo)
    wi=do/s
    return wi*zi+(1.0-wi)*zo


# -----------------------------------------------------------------------------
# Turn interpretation and template placement
# -----------------------------------------------------------------------------
def solve_road_input(line_in, pick_in, line_out, pick_out, road_width, road_layout):
    road_int=infinite_plan_intersection(line_in,line_out)
    if road_int is None:
        return None, "The selected road centrelines are parallel in plan. 180° U-turn placement will be a separate tool."
    u_in=unit2(road_int[0]-pick_in.X, road_int[1]-pick_in.Y)
    u_out=unit2(pick_out.X-road_int[0], pick_out.Y-road_int[1])
    if u_in is None or u_out is None:
        return None, "Pick the incoming line on the approach side and the outgoing line on the departure side."
    signed=math.atan2(cross2(u_in,u_out), dot2(u_in,u_out))
    angle=abs(signed)
    if angle < math.radians(5.0):
        return None, "The two travel directions are almost straight."
    if angle > math.radians(175.0):
        return None, "Near-180° turns use the dedicated U-turn/dead-end workflow (not yet in this version)."
    turn_sign=1 if signed>0 else -1
    lane_offset = road_width*0.25 if road_layout=="two_way" else 0.0
    pin=add2(road_int,right2(u_in),lane_offset)
    pout=add2(road_int,right2(u_out),lane_offset)
    path_anchor=infinite_line_intersection(pin,u_in,pout,u_out)
    if path_anchor is None:
        return None, "Could not intersect the nominal vehicle-path tangents."
    return {
        "road_int":road_int, "u_in":u_in, "u_out":u_out,
        "signed":signed, "angle":angle, "turn_sign":turn_sign,
        "lane_offset":lane_offset, "path_anchor":path_anchor,
        "grade_in":line_grade(line_in,u_in), "grade_out":line_grade(line_out,u_out),
    }, None


def typeid_for(vehicle_key, mode):
    return VEHICLE_BY_KEY[vehicle_key]["modes"].get(mode)


def available_directions(typeid):
    pref=str(typeid)+":"
    vals=[]
    for k in templates().keys():
        if k.startswith(pref):
            try: vals.append(int(k.split(":",1)[1]))
            except Exception: pass
    return sorted(set(vals))


def template_record(typeid, direction):
    return templates().get("{0}:{1}".format(typeid,int(direction)))


def transform_local_xy(local, path_anchor, u_in, turn_sign):
    # Source geometry is a RIGHT turn: incoming travel vector = (-1,0).
    x=float(local[0]); y=float(local[1])
    if turn_sign>0:  # mirror to obtain a left turn
        y=-y
    theta=math.atan2(u_in[1],u_in[0])-math.pi
    c=math.cos(theta); s=math.sin(theta)
    xm=x*c-y*s; ym=x*s+y*c
    scale=m2model(1.0)
    return (path_anchor[0]+xm*scale, path_anchor[1]+ym*scale)


def clean_points(pts, tol=None):
    if tol is None: tol=max(sc.doc.ModelAbsoluteTolerance*0.25,1e-8)
    out=[]
    for p in pts:
        if not out or p.DistanceTo(out[-1])>tol:
            out.append(p)
    return out


def native_curve(points):
    pts=clean_points(points)
    if len(pts)<2: return None
    if len(pts)==2: return rg.LineCurve(pts[0],pts[1])
    # Keep exact straight runs as lines where possible.
    ln=rg.Line(pts[0],pts[-1])
    if ln.IsValid:
        maxdev=0.0
        v=ln.Direction
        L=v.Length
        if L>1e-12:
            v.Unitize()
            for p in pts[1:-1]:
                w=p-ln.From
                dev=rg.Vector3d.CrossProduct(w,v).Length
                maxdev=max(maxdev,dev)
        if maxdev<=max(sc.doc.ModelAbsoluteTolerance, m2model(0.002)):
            return rg.LineCurve(pts[0],pts[-1])
    try:
        c=rg.Curve.CreateInterpolatedCurve(pts,3)
        if c is not None and c.IsValid:
            return c
    except Exception:
        pass
    return rg.PolylineCurve(pts)


def transformed_template(record, road, line_in, line_out):
    main_curves=[]; track_curves=[]; main_samples=[]; all_pts=[]
    for key,target in (("main",main_curves),("tracks",track_curves)):
        for chain in record.get(key,[]):
            pts=[]
            for lp in chain:
                xy=transform_local_xy(lp,road["path_anchor"],road["u_in"],road["turn_sign"])
                z=blended_z(xy,line_in,line_out)
                p=rg.Point3d(xy[0],xy[1],z)
                pts.append(p); all_pts.append(p)
                if key=="main": main_samples.append(p)
            c=native_curve(pts)
            if c is not None: target.append(c)
    return main_curves,track_curves,main_samples,all_pts


# -----------------------------------------------------------------------------
# Road corridor / fit check
# -----------------------------------------------------------------------------
def rectangle_about_segment(a,b,width):
    d=unit2(b[0]-a[0],b[1]-a[1])
    if d is None:return None
    n=left2(d); h=width*0.5
    pts=[
        rg.Point3d(a[0]+n[0]*h,a[1]+n[1]*h,0),
        rg.Point3d(b[0]+n[0]*h,b[1]+n[1]*h,0),
        rg.Point3d(b[0]-n[0]*h,b[1]-n[1]*h,0),
        rg.Point3d(a[0]-n[0]*h,a[1]-n[1]*h,0),
    ]
    pts.append(pts[0])
    return rg.PolylineCurve(pts)


def largest_closed(curves):
    best=None; best_a=-1.0
    for c in curves or []:
        if c is None or not c.IsClosed: continue
        try:
            amp=rg.AreaMassProperties.Compute(c)
            a=abs(amp.Area) if amp is not None else 0.0
        except Exception: a=0.0
        if a>best_a: best=c; best_a=a
    return best


def make_road_geometry(road,width,length,line_in,line_out):
    if width<=sc.doc.ModelAbsoluteTolerance:return None,[]
    I=road["road_int"]; ui=road["u_in"]; uo=road["u_out"]
    a=add2(I,ui,-length); b=I; c=I; d=add2(I,uo,length)
    r1=rectangle_about_segment(a,b,width); r2=rectangle_about_segment(c,d,width)
    region=None
    try:
        uni=rg.Curve.CreateBooleanUnion([r1,r2],sc.doc.ModelAbsoluteTolerance)
        region=largest_closed(uni)
    except Exception:
        region=None
    # ordinary edge lines for display/output
    edges=[]
    for p0,p1,u in ((a,b,ui),(c,d,uo)):
        n=left2(u); h=width*0.5
        for sgn in (-1.0,1.0):
            x0=(p0[0]+n[0]*h*sgn,p0[1]+n[1]*h*sgn)
            x1=(p1[0]+n[0]*h*sgn,p1[1]+n[1]*h*sgn)
            z0=blended_z(x0,line_in,line_out); z1=blended_z(x1,line_in,line_out)
            edges.append(rg.LineCurve(rg.Point3d(x0[0],x0[1],z0),rg.Point3d(x1[0],x1[1],z1)))
    return region,edges


def closest_distance(curve,p):
    try:
        ok,t=curve.ClosestPoint(p)
        if ok:return p.DistanceTo(curve.PointAt(t))
    except Exception: pass
    return float("inf")


def road_fit(main_samples,region,clearance):
    if region is None or not main_samples:return None
    tol=sc.doc.ModelAbsoluteTolerance
    worst=0.0; worstpt=None; inside_margin=float("inf")
    for p3 in main_samples:
        p=rg.Point3d(p3.X,p3.Y,0.0)
        try: cont=region.Contains(p,rg.Plane.WorldXY,tol)
        except Exception: cont=rg.PointContainment.Outside
        dist=closest_distance(region,p)
        if cont==rg.PointContainment.Outside:
            need=(0.0 if not math.isfinite(dist) else dist)+clearance
        else:
            if math.isfinite(dist):
                inside_margin=min(inside_margin,dist)
                need=max(0.0,clearance-dist)
            else:
                need=0.0
        if need>worst:
            worst=need; worstpt=p3
    return {"fits":worst<=tol,"shortfall":worst,"worst_point":worstpt,"min_edge_margin":inside_margin}


# -----------------------------------------------------------------------------
# Preview conduit
# -----------------------------------------------------------------------------
class PreviewConduit(rdisp.DisplayConduit):
    def __init__(self):
        super().__init__()
        self.main=[]; self.tracks=[]; self.road_edges=[]; self.input_lines=[]; self.worst=None

    def set_input(self,line_in,line_out):
        self.input_lines=[]
        if line_in is not None:self.input_lines.append(rg.LineCurve(line_in))
        if line_out is not None:self.input_lines.append(rg.LineCurve(line_out))

    def set_data(self,data):
        if data is None:
            self.main=[];self.tracks=[];self.road_edges=[];self.worst=None
        else:
            self.main=data.get("main",[]);self.tracks=data.get("tracks",[]);self.road_edges=data.get("road_edges",[]);self.worst=data.get("worst")

    def CalculateBoundingBox(self,e):
        try:
            bb=rg.BoundingBox.Empty
            for c in self.input_lines+self.main+self.tracks+self.road_edges:
                if c is not None: bb.Union(c.GetBoundingBox(True))
            if self.worst is not None: bb.Union(self.worst)
            if bb.IsValid:e.IncludeBoundingBox(bb)
        except Exception:pass

    def PostDrawObjects(self,e):
        try:
            for c in self.input_lines:
                e.Display.DrawCurve(c,sd.Color.FromArgb(90,90,90),1)
            for c in self.road_edges:
                e.Display.DrawCurve(c,sd.Color.Goldenrod,1)
            for c in self.tracks:
                e.Display.DrawCurve(c,sd.Color.DodgerBlue,1)
            for c in self.main:
                e.Display.DrawCurve(c,sd.Color.OrangeRed,2)
            if self.worst is not None:
                e.Display.DrawPoint(self.worst,rg.PointStyle.RoundControlPoint,5,sd.Color.Red)
        except Exception:
            pass


